module top_module (
        input clk,
        input areset,
        input x,
        output reg z);parameter Cool=2'b00, Heat=2'b01, Off=2'b10;
	reg [1:0] state;
	always @(posedge clk, posedge areset) begin
		if (areset)
			state <= Cool;
		else begin
			case (state)
				Cool: state <= x ? Heat : Off;
				Heat: state <= x ? Heat : Cool;
				Off: state <= x ? Cool : Off;
			endcase
		end
	end

	assign z = (state == Heat);

endmodule

