module binary_counter_32bit(
    input wire clk,
    input wire rst,
    output reg [31:0] count
);

always @(posedge clk or posedge rst) begin
    if (rst) begin
        count <= 32'b00000000000000000000000000000000;
    end else begin
        count <= count + 1;
    end
end

endmodule

