module top_module(
	address_a,
	address_b,
	data_a,
	data_b,
	clock_a,
	clock_b,
	wren_a,
	wren_b,
	q_a,
	q_b
);parameter WORDS = 64;
	parameter WIDTH = 8;
	parameter ADDR_WIDTH = $clog2(WORDS); // Use $clog2 to determine address width

	input [ADDR_WIDTH-1:0] address_a;
	input [ADDR_WIDTH-1:0] address_b;
	input [WIDTH-1:0] data_a;
	input [WIDTH-1:0] data_b;
	input clock_a;
	input clock_b;
	input wren_a;
	input wren_b;
	output reg [WIDTH-1:0] q_a;
	output reg [WIDTH-1:0] q_b;

	reg [WIDTH-1:0] mem [0:WORDS-1];

	always @(posedge clock_a) begin
		if (wren_a) begin
			mem[address_a] <= data_a;
		end
		q_a <= mem[address_a];
	end

	always @(posedge clock_b) begin
		if (wren_b) begin
			mem[address_b] <= data_b;
		end
		q_b <= mem[address_b];
	end

endmodule

