description:
Design a frequency divider circuit that takes an input clock signal and generates an output clock signal with a frequency that is halved compared to the input. The divider is parameterized to allow for custom division factors, specifically designed to accommodate a division of 50,000,000 in this case. The output clock transitions on every rising edge of the input clock, toggling its state when a specific count (half of the divider value) is reached, effectively reducing the frequency of the output clock signal.
module top_module(
	input clk_in,
	output reg clk_out
);

code:
module top_module(
	input clk_in,
	output reg clk_out
);parameter DIV_BITS = 64;
parameter DIVIDER	= 50000000;

reg [0:DIV_BITS-1] cnt = 0;
reg clk_out_state = 0;


always @(posedge clk_in)
begin
	cnt = cnt + { {DIV_BITS-1{1'b0}}, 1'b1 };
	if (cnt == DIVIDER / 2) begin
		clk_out_state = !clk_out_state;
		clk_out = clk_out_state;
		cnt = 0;
	end
end
endmodule

