module top_module(empty,
    full,
    data_count,
    dout,
    clk,
    din,
    rst,
    rd_en,
    wr_en);output empty;
  output full;
  output [8:0] data_count; // Changed from [0:0] to [8:0] to hold full range
  output [23:0] dout;
  input clk;
  input [23:0] din;
  input rst;
  input rd_en;
  input wr_en;

  reg [23:0] fifo_mem [511:0]; // Declare fifo_mem as reg for storage
  reg [8:0] wr_ptr; // Changed wire to reg for pointers
  reg [8:0] rd_ptr; // Changed wire to reg for pointers
  reg [8:0] data_count_wire; // Changed wire to reg to allow assignments in always block
  reg empty;
  reg full;
  reg rd_en_internal;
  reg wr_en_internal;
  reg [23:0] dout_internal;

  assign empty = (data_count_wire == 0);
  assign full = (data_count_wire == 512);
  assign data_count = data_count_wire;

  // read pointer logic
  always @(posedge clk) begin
    if (rst) begin
      rd_ptr <= 0;
    end else if (rd_en_internal) begin
      rd_ptr <= rd_ptr + 1;
    end
  end

  // write pointer logic
  always @(posedge clk) begin
    if (rst) begin
      wr_ptr <= 0;
    end else if (wr_en_internal) begin
      wr_ptr <= wr_ptr + 1;
    end
  end

  // data count logic
  always @(posedge clk) begin
    if (rst) begin
      data_count_wire <= 0;
    end else if (rd_en_internal && !empty) begin
      data_count_wire <= data_count_wire - 1;
    end else if (wr_en_internal && !full) begin
      data_count_wire <= data_count_wire + 1;
    end
  end

  // read enable logic
  always @* begin
    rd_en_internal = (rd_en && !empty);
  end

  // write enable logic
  always @* begin
    wr_en_internal = (wr_en && !full);
  end

  // data output logic
  assign dout_internal = fifo_mem[rd_ptr];

  // FIFO memory write logic
  always @(posedge clk) begin
    if (rst) begin
      integer i;
      for (i = 0; i < 512; i = i + 1) begin
        fifo_mem[i] <= 0; // Initialize memory on reset
      end
    end else if (wr_en_internal) begin
      fifo_mem[wr_ptr] <= din;
    end
  end

  assign dout = dout_internal;
endmodule

