description:
Design a button debouncing circuit that detects a rising edge on an input signal. The module samples the input signal at the positive edge of the clock and resets with a high signal. It stores the current and previous input states in a two-bit register and outputs a high signal (1) only when a transition from low to high occurs, thereby filtering out any noise from the mechanical button press. This design ensures that the output signal reflects a stable transition rather than erratic fluctuations caused by bouncing.
module top_module(
  clk,rst,input_sig,output_sig
    );

code:
module top_module(
  clk,rst,input_sig,output_sig
    );input clk,rst;
   input input_sig;
   output wire output_sig;

   reg [1:0] rinput;


   always @(posedge clk, posedge rst)
   begin 
    if(rst) begin  rinput<=0; end 
    else begin
      rinput[1]<=rinput[0];
      rinput[0]<=input_sig;
    end 
   end

  assign output_sig=(~rinput[1]&&rinput[0])?1:0;

endmodule

