module fsm (
	input clk,
	input reset_n,
	input m,
	input n,
	output reg v);

	parameter H=0, I=1, S1=2, S2=3;
	reg [1:0] state, next;

	always @(posedge clk) begin
		if (!reset_n) state <= H;
		else state <= next;
	end

	always_comb begin
		case (state)
			H: next = m ? I : H;
			I: next = n ? S1 : S2;
			S1: next = n ? S2 : H;
			S2: next = m ? I : H;
			default: next = 'x;
		endcase
	end

	assign v = (state == S1);

endmodule

