module top_module(
    input D,
    input SLEEP_B,
    input VPWR,
    input VGND,
    input VPB,
    input VNB,
    output Q
);reg Q_reg;
reg D_reg;
reg SLEEP_B_reg;
reg VPWR_reg;
reg VGND_reg;
reg VPB_reg;
reg VNB_reg;

always @(posedge VPWR or negedge VGND) begin
