  out_m = in_m << 3; 
  end else if (in_m[46:44] == 3'b001) begin 
  out_e = in_e - 2; 
  out_m = in_m << 2; 
  end else if (in_m[46:45] == 2'b01) begin 
  out_e = in_e - 1; 
  out_m = in_m << 1; 
