description:
Design a decade counter that increments the count on each rising edge of the clock and resets to zero upon receiving an active low reset signal. This counter counts from 0 to 9 and then rolls over back to 0, outputting the 4-bit count value at all times.
module top_module(
  input clk,
  input reset_n,
  output [3:0] count
);

code:
module top_module(
  input clk,
  input reset_n,
  output [3:0] count
);reg [3:0] counter = 4'd0;

  always @(posedge clk, negedge reset_n) begin
    if (!reset_n) begin
      counter <= 4'd0;
    end else if (counter == 4'd9) begin
      counter <= 4'd0;
    end else begin
      counter <= counter + 1;
    end
  end

  assign count = counter;

endmodule

